import { test, expect } from '@playwright/test';

test.describe('Dynamic Content Loading Functionality', () => {
  test('should not reveal the hidden content initially', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page.locator('#finish')).toBeVisible();
  });

  test('should reveal the hidden content after clicking the Start button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('#start button');
    await expect(page.locator('#loading')).toBeVisible();
    await expect(page.locator('#finish')).toBeVisible();
    await expect(page.locator('#finish')).toHaveText('Hello World!');
  });
});
